css:
:root{--navy:#073d78;--navy-dark:#052f5e;--blue:#1267bd;--red:#d7192e;--pale:#eef7fd;--line:#dce9f4;--muted:#5f7387;
--bs-body-font-family:"DM Sans",Arial,sans-serif;--bs-body-color:#173c63;--bs-link-hover-color:var(--navy);
--shadow:0 14px 40px rgba(7,61,120,.10);--radius:20px;--header-h:80px}
html{scroll-behavior:smooth;scroll-padding-top:var(--header-h)}
@media(min-width:1920px){html{font-size:18px}}
@media(min-width:2560px){html{font-size:24px}}
@media(min-width:3200px){html{font-size:28px}}
body{overflow-x:hidden}
a,a:hover,a:focus{text-decoration:none}
h1,h2,h3,h4{font-family:Manrope,sans-serif;color:var(--navy);letter-spacing:-.02em}
.wrap{width:100%;max-width:1320px;margin-inline:auto;padding-inline:1.25rem}
@media(min-width:1920px){.wrap{max-width:1560px}}
@media(min-width:2560px){.wrap{max-width:1900px}}
@media(min-width:3200px){.wrap{max-width:2200px}}
:focus-visible{outline:3px solid rgba(18,103,189,.45);outline-offset:2px}
.btn-arsh{--bs-btn-bg:var(--red);--bs-btn-border-color:var(--red);--bs-btn-color:#fff;--bs-btn-hover-bg:#b9132a;--bs-btn-hover-border-color:#b9132a;--bs-btn-hover-color:#fff;--bs-btn-active-bg:#a31024;--bs-btn-active-border-color:#a31024;--bs-btn-active-color:#fff;font-weight:600;border-radius:10px;padding:.65rem 1.2rem;font-size:.92rem;box-shadow:0 8px 18px rgba(215,25,46,.2)}
.btn-ghost{--bs-btn-bg:#fff;--bs-btn-color:var(--blue);--bs-btn-border-color:#cfe2f3;--bs-btn-hover-bg:var(--pale);--bs-btn-hover-color:var(--navy);--bs-btn-hover-border-color:#b6d3ec;font-weight:600;border-radius:10px;padding:.65rem 1.2rem;font-size:.92rem}

/* Header */
.topbar{background:var(--navy-dark);color:#cfe1f2;font-size:.78rem}
.topbar a{color:#fff;font-weight:600}
.site-header{position:sticky;top:0;z-index:1030;background:rgba(255,255,255,.92);backdrop-filter:blur(14px);border-bottom:1px solid #e5edf4;height:var(--header-h)}
.site-header .wrap{height:100%;display:flex;align-items:center;gap:1rem}
.logo img{height:46px;width:auto;display:block}
.main-nav{display:flex;align-items:center;gap:.25rem;margin-left:auto}
.main-nav a{padding:.5rem .85rem;border-radius:10px;font-size:.88rem;font-weight:600;color:#244665;transition:background .2s,color .2s}
.main-nav a:hover,.main-nav a.active{background:var(--pale);color:var(--blue)}
.menu-btn{width:44px;height:44px;border:1px solid var(--line);border-radius:12px;background:#fff;color:var(--navy);font-size:1.5rem;display:none;align-items:center;justify-content:center;padding:0}
.search-btn{width:42px;height:42px;border:1px solid var(--line);border-radius:50%;background:#fff;color:var(--navy);font-size:1rem;display:flex;align-items:center;justify-content:center;padding:0;flex:none;transition:.2s}
.search-btn:hover{background:var(--pale);color:var(--blue)}

/* Search modal */
.sm{position:fixed;inset:0;z-index:1070;display:none;align-items:flex-start;justify-content:center;padding:12vh 1rem 1rem;background:rgba(5,30,60,.6);backdrop-filter:blur(4px)}
.sm.open{display:flex}
.sm-box{width:min(640px,100%);background:#fff;border-radius:20px;padding:1.25rem;box-shadow:0 30px 70px rgba(5,30,60,.35)}
.sm-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:.9rem}
.sm-head h2{font-size:1.05rem;font-weight:700;margin:0}
.sm-close{width:36px;height:36px;border:0;border-radius:50%;background:var(--pale);color:var(--navy);display:flex;align-items:center;justify-content:center;padding:0}
.sm-box .input-group-text{height:3rem;background:#f8fbfe;border:1px solid #d3e3f1;border-right:0;border-radius:12px 0 0 12px;color:var(--blue)}
.sm-box .form-control{height:3rem;border:1px solid #d3e3f1;border-left:0;border-right:0;border-radius:0;background:#f8fbfe;font-size:.95rem}
.sm-box .btn{height:3rem;border-radius:0 12px 12px 0;box-shadow:none}
.sm-chips{display:flex;flex-wrap:wrap;gap:.45rem;margin-top:.9rem}
.sm-chips button{border:1px solid var(--line);background:#fff;color:var(--blue);border-radius:999px;padding:.3rem .8rem;font-size:.8rem;font-weight:500}
.sm-chips button:hover{background:var(--pale)}

/* Drawer */
.scrim{position:fixed;inset:0;background:rgba(5,30,60,.55);backdrop-filter:blur(3px);opacity:0;visibility:hidden;transition:.3s;z-index:1040}
.drawer{position:fixed;top:0;right:0;bottom:0;width:min(86vw,360px);background:#fff;z-index:1050;transform:translateX(100%);transition:transform .35s cubic-bezier(.22,.8,.3,1);display:flex;flex-direction:column;box-shadow:-20px 0 50px rgba(7,61,120,.2)}
.drawer-open .scrim{opacity:1;visibility:visible}
.drawer-open .drawer{transform:none}
.drawer-open{overflow:hidden}
.drawer-top{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--line)}
.drawer-top img{height:40px}
.drawer-close{width:40px;height:40px;border:0;border-radius:50%;background:var(--pale);color:var(--navy);font-size:1.1rem;padding:0;display:flex;align-items:center;justify-content:center}
.drawer-links{flex:1;overflow-y:auto;padding:.75rem 1rem}
.drawer-links a{display:flex;align-items:center;gap:.9rem;padding:.8rem .7rem;border-radius:14px;font-weight:600;font-size:.95rem;color:var(--navy)}
.drawer-links a i{width:38px;height:38px;border-radius:12px;background:var(--pale);color:var(--blue);display:grid;place-items:center;font-size:1.05rem}
.drawer-links a:hover,.drawer-links a.active{background:var(--pale)}
.drawer-links a::after{content:"\F285";font-family:"bootstrap-icons";margin-left:auto;color:#9bb3c9;font-size:.8rem}
.drawer-foot{padding:1.1rem 1.25rem 1.5rem;border-top:1px solid var(--line);background:var(--pale)}
.drawer-emerg{display:flex;align-items:center;gap:.75rem;margin-bottom:.9rem;color:var(--navy);font-weight:700}
.drawer-emerg i{width:40px;height:40px;border-radius:50%;background:var(--red);color:#fff;display:grid;place-items:center}
.drawer-emerg small{display:block;font-weight:500;color:var(--muted)}
@media(max-width:991.98px){.main-nav,.header-cta{display:none}.menu-btn{display:flex}.search-btn{margin-left:auto}:root{--header-h:66px}}

/* Page hero */
.page-hero{background:radial-gradient(circle at 15% 20%,#fff 0,var(--pale) 55%,#e3f1fb 100%);padding:clamp(2rem,4.5vw,4rem) 0 clamp(2.4rem,5vw,4.4rem)}
.crumb{display:flex;align-items:center;gap:.5rem;font-size:.82rem;color:var(--muted);margin-bottom:1rem}
.crumb a{color:var(--blue);font-weight:600}
.page-hero h1{font-size:clamp(2rem,3.8vw,3.4rem);line-height:1.08;font-weight:800;margin:0 0 .9rem}
.page-hero h1 span{color:var(--red)}
.page-hero .lead{color:#49647d;font-size:clamp(.95rem,1.15vw,1.1rem);max-width:38rem;margin:0}
.hero-pills{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:1.4rem}
.hero-pills a{background:#fff;border:1px solid var(--line);border-radius:999px;padding:.35rem .9rem;font-size:.82rem;font-weight:600;color:var(--blue);transition:.2s}
.hero-pills a:hover{background:var(--navy);border-color:var(--navy);color:#fff}
.hero-stats{display:flex;gap:2rem;flex-wrap:wrap}
.hero-stats strong{display:block;font-family:Manrope;font-size:1.6rem;color:var(--navy)}
.hero-stats span{font-size:.8rem;color:var(--muted)}

/* Sections */
.section{padding:clamp(2.6rem,5.5vw,5.5rem) 0}
.kicker{display:inline-flex;align-items:center;gap:.5rem;color:var(--red);font-weight:600;font-size:.85rem;margin-bottom:.4rem}
.kicker::before{content:"";width:22px;height:3px;border-radius:3px;background:var(--red)}
.title{font-size:clamp(1.5rem,2.8vw,2.4rem);line-height:1.15;font-weight:700;margin:0}

/* Speciality cards */
.sp-card{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:1.5rem;height:100%;display:flex;flex-direction:column;box-shadow:0 6px 22px rgba(7,61,120,.06);transition:.25s}
.sp-card:hover{border-color:#a9cde9;box-shadow:var(--shadow);transform:translateY(-3px)}
.sp-top{display:flex;align-items:center;gap:.9rem;margin-bottom:.9rem}
.sp-icon{width:58px;height:58px;border-radius:16px;background:linear-gradient(135deg,#e6f2fd,#d3e8fa);color:var(--blue);display:grid;place-items:center;font-size:1.6rem;flex:none}
.sp-card h3{font-size:1.1rem;font-weight:700;margin:0;line-height:1.25}
.sp-card p{color:var(--muted);font-size:.88rem;line-height:1.6;margin:0 0 1rem}
.sp-list{list-style:none;padding:0;margin:0 0 1.2rem;display:grid;gap:.45rem}
.sp-list li{display:flex;gap:.55rem;font-size:.84rem;color:#2c4a68;font-weight:500}
.sp-list i{color:var(--red);font-size:.85rem;margin-top:.15rem}
.sp-foot{margin-top:auto;display:flex;justify-content:space-between;align-items:center;gap:.5rem;border-top:1px solid var(--line);padding-top:1rem}
.sp-foot a{font-weight:600;font-size:.86rem;color:var(--blue)}
.sp-foot a:hover{color:var(--navy)}
.sp-foot .book{background:var(--red);color:#fff;border-radius:9px;padding:.4rem .9rem;font-size:.8rem}
.sp-foot .book:hover{background:#b9132a;color:#fff}

/* Support services */
.support-section{background:linear-gradient(180deg,#f5faff,#eaf4fc)}
.sv{display:flex;align-items:center;gap:.8rem;background:#fff;border:1px solid var(--line);border-radius:16px;padding:1rem 1.1rem;height:100%;transition:.2s}
.sv:hover{border-color:#a9cde9;box-shadow:var(--shadow)}
.sv i{width:44px;height:44px;border-radius:13px;background:var(--pale);color:var(--blue);display:grid;place-items:center;font-size:1.2rem;flex:none}
.sv b{display:block;font-size:.92rem;color:var(--navy);line-height:1.2}
.sv small{color:var(--muted);font-size:.76rem}

/* CTA */
.cta{background:#fff;border:1px solid var(--line);border-radius:24px;padding:clamp(1.4rem,3vw,2.4rem);box-shadow:var(--shadow);display:flex;align-items:center;justify-content:space-between;gap:1.5rem;flex-wrap:wrap}
.cta h2{font-size:clamp(1.25rem,2.2vw,1.8rem);font-weight:700;margin:0 0 .3rem}
.cta p{margin:0;color:var(--muted);font-size:.92rem}

/* Emergency strip + footer */
.strip{background:linear-gradient(110deg,var(--navy-dark),var(--navy));color:#fff;padding:.9rem 0}
.strip .wrap{display:flex;justify-content:space-between;align-items:center;gap:1rem;flex-wrap:wrap}
.strip .lft{display:flex;align-items:center;gap:.9rem}
.strip-ic{width:38px;height:38px;border-radius:50%;background:var(--red);color:#fff;display:flex;align-items:center;justify-content:center;flex:none;box-shadow:0 0 0 6px rgba(215,25,46,.22)}
.strip b{font-family:Manrope;font-weight:700;font-size:1rem}
.strip small{display:block;color:#b9d0e6;font-size:.78rem}
.call{background:var(--red);color:#fff;border-radius:999px;padding:.4rem 1rem;font-size:.85rem;font-weight:600}
.call:hover{color:#fff;background:#b9132a}
footer{background:#041f3f;color:#9fb8ce;padding:2.2rem 0 1rem;font-size:.8rem;border-top:3px solid var(--red)}
footer h6{color:#e6f0f9;font-weight:600;font-size:.82rem;margin-bottom:.8rem}
footer a{color:#9fb8ce;display:block;margin-bottom:.4rem}
footer a:hover{color:#fff}
footer p{margin:0 0 .8rem;max-width:26rem;line-height:1.55}
footer .fl a{transition:color .2s,padding-left .2s}
footer .fl a:hover{padding-left:.25rem}
.social{display:flex;gap:.5rem}
.social a{width:32px;height:32px;border-radius:50%;background:rgba(255,255,255,.08);display:flex;align-items:center;justify-content:center;margin:0;color:#cfe1f2}
.social a:hover{background:var(--red)}
.fi{display:flex;gap:.55rem;margin-bottom:.45rem;color:#9fb8ce}
.copy{display:flex;justify-content:space-between;flex-wrap:wrap;gap:.4rem;border-top:1px solid rgba(255,255,255,.08);margin-top:1.5rem;padding-top:1rem;font-size:.74rem;color:#7f9bb3}
.copy a{display:inline;margin:0;color:#cfe1f2;font-weight:600}
.copy a:hover{color:#fff}

/* Icon centering */
.drawer-close .bi,.menu-btn .bi,.search-btn .bi,.sm-close .bi,.sp-icon .bi,.sv>i,.drawer-links a>i,.drawer-emerg .bi,.social .bi{display:flex;align-items:center;justify-content:center;line-height:1}
.drawer-close .bi::before,.menu-btn .bi::before,.search-btn .bi::before,.sm-close .bi::before,.sp-icon .bi::before,.sv>i::before,.drawer-links a>i::before,.drawer-emerg .bi::before,.social .bi::before{display:block;vertical-align:0;line-height:1}
@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}

.sp-card{position:relative}.sp-card-hitarea{position:absolute;inset:0;z-index:1;border-radius:inherit}.sp-card .sp-foot{position:relative;z-index:2}

/* About and contact pages */
.about-overview-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:3rem;align-items:center}.about-overview p{max-width:800px;color:var(--muted);font-size:1rem;line-height:1.8}
.about-stat-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}.about-stat{min-height:145px;border:1px solid var(--line);border-radius:18px;background:linear-gradient(145deg,#fff,#f1f8fd);padding:1.35rem;display:flex;flex-direction:column;justify-content:center;box-shadow:0 12px 30px rgba(7,61,120,.06)}.about-stat strong{font:800 2.3rem Manrope;color:var(--navy)}.about-stat span{color:var(--muted);font-weight:600}
.about-values{background:#f3f8fc}.about-value-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem;margin-top:1.6rem}.about-value-grid article{background:#fff;border:1px solid var(--line);border-radius:18px;padding:1.4rem;min-height:195px}.about-value-grid article>span{width:46px;height:46px;border-radius:14px;background:#e7f3fc;color:var(--blue);display:grid;place-items:center;font-size:1.25rem}.about-value-grid h3{font-size:1.02rem;margin:1rem 0 .45rem}.about-value-grid p{color:var(--muted);font-size:.9rem;line-height:1.6;margin:0}
.about-leader-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.2rem;margin-top:1.5rem}.about-leader{background:#fff;border:1px solid var(--line);border-radius:22px;overflow:hidden;box-shadow:0 14px 36px rgba(7,61,120,.08)}.about-leader>img{width:100%;height:340px;object-fit:cover;object-position:center 32%;display:block;background:#eaf2f8}.about-leader>div{padding:1.5rem}.leader-role{font-size:.72rem;letter-spacing:.14em;font-weight:800;color:var(--red)}.about-leader h3{margin:.35rem 0;font-size:1.45rem}.leader-credentials{font-size:.88rem;color:var(--blue);font-weight:700}.about-leader p{color:var(--muted);line-height:1.7}.about-leader blockquote{border-left:3px solid var(--red);margin:1rem 0 0;padding:.2rem 0 .2rem 1rem;color:var(--navy);font-weight:600;line-height:1.65}
.about-purpose{background:#063d72}.about-purpose-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.2rem}.about-purpose-grid article{border:1px solid rgba(255,255,255,.2);background:rgba(255,255,255,.07);border-radius:22px;padding:2rem;color:#fff}.purpose-label{display:flex;align-items:center;gap:.6rem;font-size:.75rem;letter-spacing:.15em;font-weight:800;color:#bfe1ff}.purpose-label i{font-size:1.2rem}.about-purpose-grid h2{color:#fff;font-size:clamp(1.2rem,2vw,1.7rem);line-height:1.55;margin:1rem 0 0;letter-spacing:-.01em}
.about-bottom-cta .wrap{display:flex;align-items:center;justify-content:space-between;gap:1.5rem;flex-wrap:wrap}.about-bottom-cta .title{margin-bottom:0}.contact-main{background:#f4f8fc}.contact-intro{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1.5rem}.contact-intro p{color:var(--muted);max-width:560px;margin:0}.contact-emergency{min-width:225px;padding:1rem 1.2rem;border-radius:16px;background:#fff;border:1px solid #f1c9cf;display:grid;grid-template-columns:42px 1fr;column-gap:.8rem;color:var(--navy)}.contact-emergency>span{grid-row:span 2;width:42px;height:42px;border-radius:50%;background:#fff0f2;color:var(--red);display:grid;place-items:center}.contact-emergency small{color:var(--muted)}.contact-emergency strong{font-size:.95rem}
.contact-grid{display:grid;grid-template-columns:.85fr 1.15fr;gap:1.2rem;align-items:start}.contact-details{display:grid;gap:.85rem}.contact-card{display:flex;gap:1rem;padding:1.25rem;background:#fff;border:1px solid var(--line);border-radius:18px}.contact-icon{flex:none;width:44px;height:44px;border-radius:14px;background:#eaf4fc;color:var(--blue);display:grid;place-items:center;font-size:1.1rem}.contact-card h3{font-size:1rem;margin:.1rem 0 .55rem}.contact-card p{color:var(--muted);font-size:.9rem;line-height:1.65;margin:0 0 .55rem}.contact-card a{color:var(--blue);font-weight:700}.contact-hours{display:flex;gap:.8rem;align-items:center;padding:1rem 1.2rem;border-radius:16px;background:#073d78;color:#fff}.contact-hours>i{font-size:1.3rem;color:#cde6ff}.contact-hours small{display:block;color:#d5e7f7;margin-top:.2rem}.contact-form-card{padding:1.6rem;background:#fff;border:1px solid var(--line);border-radius:20px;box-shadow:0 14px 36px rgba(7,61,120,.07)}.contact-form-card h2{font:800 1.45rem Manrope;color:var(--navy);margin:.3rem 0}.contact-form-card>p{color:var(--muted);font-size:.9rem}.contact-form-card form{display:grid;gap:1rem}.contact-form-card label{display:grid;gap:.45rem;font-size:.84rem;font-weight:700;color:#244665}.contact-form-row{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.9rem}.contact-form-card .form-control{min-height:46px;border-color:#d8e5ef;border-radius:10px}.contact-form-card textarea.form-control{min-height:130px;resize:vertical}.contact-form-card .btn{justify-self:start}.contact-form-note{color:var(--muted)}.contact-form-note a{font-weight:700;color:var(--red)}
@media(max-width:991.98px){.about-overview-grid,.contact-grid{grid-template-columns:1fr}.about-value-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.about-leader>img{height:300px}}
@media(max-width:575.98px){.about-hero{height:auto;min-height:340px;padding:28px 0}.about-value-grid,.about-leader-grid,.about-purpose-grid,.contact-form-row{grid-template-columns:1fr}.about-stat{min-height:115px}.contact-intro{align-items:flex-start;flex-direction:column}.contact-emergency{width:100%}.about-leader>img{height:280px}.contact-form-card{padding:1.2rem}}
